const HEX_DIGITS = new Set("0123456789abcdefABCDEF");

/** @param {string | undefined} ch @returns {boolean} */
function isHexDigit(ch) {
	return HEX_DIGITS.has(ch);
}

/** @param {string} ch @returns {boolean} */
function isUnreserved(ch) {
	return (
		(ch >= "A" && ch <= "Z") ||
		(ch >= "a" && ch <= "z") ||
		(ch >= "0" && ch <= "9") ||
		ch === "-" ||
		ch === "." ||
		ch === "_" ||
		ch === "~"
	);
}

/**
 * R2: decode percent escapes. Unreserved characters are decoded; every
 * other valid escape stays an escape with upper-cased hex digits.
 * @param {string} path
 * @returns {string}
 */
function decodeEscapes(path) {
	let out = "";
	for (let i = 0; i < path.length; i++) {
		const ch = path[i];
		if (ch !== "%") {
			out += ch;
			continue;
		}
		const hi = path[i + 1];
		const lo = path[i + 2];
		if (!isHexDigit(hi) || !isHexDigit(lo)) {
			throw new SyntaxError(
				`invalid percent escape in route path at index ${i}`,
			);
		}
		const decodedChar = String.fromCharCode(parseInt(hi + lo, 16));
		out += isUnreserved(decodedChar)
			? decodedChar
			: `%${(hi + lo).toUpperCase()}`;
		i += 2;
	}
	return out;
}

/**
 * @param {string} path
 * @returns {string}
 */
export function normalizeRoute(path) {
	// R1 (reported before R2 and R4, per R7)
	if (
		typeof path !== "string" ||
		path === "" ||
		path[0] !== "/" ||
		path.includes("?") ||
		path.includes("#")
	) {
		throw new TypeError(
			"path must be a string starting with '/' and must not contain '?' or '#'",
		);
	}

	// R2 (reported before R4, per R7)
	const decoded = decodeEscapes(path);

	// R3: drop empty segments produced by repeated (or trailing) slashes
	const segments = decoded.split("/").slice(1).filter((s) => s !== "");

	// R5: trailing slash if the original path ended with '/' or the last
	// segment (after R2) is '.' or '..'
	const lastSegment = segments[segments.length - 1];
	const keepTrailingSlash =
		decoded.endsWith("/") || lastSegment === "." || lastSegment === "..";

	// R4
	const result = [];
	for (const segment of segments) {
		if (segment === ".") {
			continue;
		}
		if (segment === "..") {
			if (result.length === 0) {
				throw new RangeError(
					"route path escapes the root: '..' without a segment before it",
				);
			}
			result.pop();
		} else {
			result.push(segment);
		}
	}

	if (result.length === 0) {
		return "/";
	}
	return `/${result.join("/")}${keepTrailingSlash ? "/" : ""}`;
}

